  v_recipes jsonb := '[{"title":"Vegetable Poha","description":"Soft flattened rice with potato, peas and peanuts, finished with lemon.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":15,"steps":["Rinse the poha in a sieve under running water, drain and leave 5 minutes to soften.","Heat the oil, add mustard seeds; when they splutter add the peanuts and fry 1 minute.","Add chopped onion, green chilli and diced potato; cover and cook 6–8 minutes until the potato is soft.","Stir in peas, turmeric, salt and sugar, then the poha. Mix gently and heat through for 2 minutes.","Squeeze over the lemon and scatter the coriander."],"lines":[{"ingredient":"poha","grams":120,"display":"1½ cups"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"potato","grams":80,"display":"1 small"},{"ingredient":"green peas","grams":40,"display":"¼ cup"},{"ingredient":"peanuts","grams":20,"display":"2 tbsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"lemon","grams":30,"display":"½"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"sugar","grams":5,"display":"1 tsp"}]},{"title":"Jain Poha","description":"Poha without onion or potato — peas, capsicum and peanuts instead.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":12,"steps":["Rinse the poha, drain and leave 5 minutes to soften.","Heat the oil, splutter the mustard seeds, then fry the peanuts for 1 minute.","Add green chilli, capsicum and peas; cook 4 minutes.","Add turmeric, salt, sugar and the poha; mix gently and heat 2 minutes. Finish with lemon and coriander."],"lines":[{"ingredient":"poha","grams":120,"display":"1½ cups"},{"ingredient":"green peas","grams":50,"display":"⅓ cup"},{"ingredient":"capsicum","grams":50,"display":"½"},{"ingredient":"peanuts","grams":20,"display":"2 tbsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"lemon","grams":30,"display":"½"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"sugar","grams":5,"display":"1 tsp"}]},{"title":"Vegetable Upma","description":"Roasted semolina cooked with vegetables and a mustard-seed tempering.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":15,"steps":["Dry-roast the semolina in a pan for 4–5 minutes until fragrant; set aside.","Heat the oil, splutter the mustard seeds, then add onion, ginger and green chilli and cook 2 minutes.","Add the carrot and peas and cook 3 minutes. Pour in 500 ml water with the salt and bring to a boil.","Lower the heat and pour in the semolina slowly, stirring all the time. Cover for 2–3 minutes, then fluff and add coriander."],"lines":[{"ingredient":"semolina","grams":100,"display":"⅔ cup"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"carrot","grams":40,"display":"½"},{"ingredient":"green peas","grams":30,"display":"3 tbsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"ginger","grams":5,"display":"1 tsp grated"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"}]},{"title":"Jain Vegetable Upma","description":"Upma with capsicum, tomato, peas and cashews — no onion, ginger or roots.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":15,"steps":["Dry-roast the semolina for 4–5 minutes until fragrant; set aside.","Heat the oil, splutter the mustard seeds, fry the cashews golden, then add green chilli, capsicum, tomato and peas for 3 minutes.","Add 500 ml water and the salt; bring to a boil.","Pour in the semolina slowly while stirring, cover 2–3 minutes, then fluff and add coriander."],"lines":[{"ingredient":"semolina","grams":100,"display":"⅔ cup"},{"ingredient":"capsicum","grams":40,"display":"⅓"},{"ingredient":"tomato","grams":50,"display":"1 small"},{"ingredient":"green peas","grams":30,"display":"3 tbsp"},{"ingredient":"cashews","grams":10,"display":"6–8"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"}]},{"title":"Masala Oats","description":"Savoury oats cooked with vegetables and Indian spices.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":5,"cook":12,"steps":["Heat the oil, add cumin seeds, then onion; cook 2 minutes.","Add tomato, carrot and peas with turmeric, chilli powder and salt; cook 4 minutes.","Add the oats and 400 ml water. Simmer 4–5 minutes, stirring, until creamy. Top with coriander."],"lines":[{"ingredient":"rolled oats","grams":100,"display":"1 cup"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"carrot","grams":30,"display":"¼"},{"ingredient":"green peas","grams":30,"display":"3 tbsp"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"}]},{"title":"Banana Oats Porridge","description":"Oats simmered in milk with banana, almonds and a little jaggery.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":5,"cook":8,"steps":["Bring the milk to a simmer, add the oats and cook 4–5 minutes, stirring.","Stir in the jaggery until it melts.","Serve topped with sliced banana and chopped almonds."],"lines":[{"ingredient":"rolled oats","grams":80,"display":"¾ cup"},{"ingredient":"milk","grams":400,"display":"1⅔ cups"},{"ingredient":"banana","grams":120,"display":"1"},{"ingredient":"almonds","grams":15,"display":"10–12"},{"ingredient":"jaggery","grams":10,"display":"2 tsp"}]},{"title":"Moong Dal Chilla","description":"Protein-rich savoury pancakes from soaked yellow moong dal.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":15,"cook":15,"steps":["Soak the moong dal 3–4 hours, drain and grind with green chilli and a little water to a smooth, pourable batter.","Stir in salt, cumin, chopped tomato and coriander.","Spread a ladle of batter thinly on a hot greased tawa, drizzle oil around and cook until golden on both sides."],"lines":[{"ingredient":"moong dal","grams":120,"display":"¾ cup (dry)"},{"ingredient":"tomato","grams":40,"display":"½"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Besan Chilla","description":"Quick gram-flour pancakes with onion, tomato and coriander.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":15,"steps":["Whisk the besan with about 180 ml water, turmeric, chilli powder and salt into a smooth batter.","Stir in finely chopped onion, tomato, green chilli and coriander.","Pour a ladleful onto a hot greased tawa, spread thin and cook 2 minutes per side with a little oil."],"lines":[{"ingredient":"besan","grams":100,"display":"1 cup"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"tomato","grams":50,"display":"1 small"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Idli with Coconut Chutney","description":"Steamed rice-and-urad-dal cakes with fresh coconut chutney.","cuisine":"indian","meal_types":["breakfast"],"servings":3,"prep":20,"cook":15,"steps":["Soak rice and urad dal separately for 5 hours. Grind each smoothly, mix with salt and leave to ferment overnight.","Pour the batter into greased idli moulds and steam 10–12 minutes.","For the chutney, grind the coconut with green chilli, a pinch of salt and a little water.","Temper with mustard seeds spluttered in the oil and pour over the chutney."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"urad dal","grams":50,"display":"¼ cup"},{"ingredient":"fresh coconut","grams":60,"display":"½ cup grated"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"sunflower oil","grams":5,"display":"1 tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Plain Dosa with Coconut Chutney","description":"Crisp fermented rice-and-lentil crêpes with coconut chutney.","cuisine":"indian","meal_types":["breakfast"],"servings":3,"prep":20,"cook":20,"steps":["Soak rice and urad dal 5 hours, grind to a smooth batter with salt and ferment overnight.","Spread a ladle of batter in a thin circle on a very hot tawa, drizzle oil and cook until crisp and golden.","Grind the coconut with green chilli, salt and a little water for the chutney."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"urad dal","grams":50,"display":"¼ cup"},{"ingredient":"sunflower oil","grams":20,"display":"4 tsp"},{"ingredient":"fresh coconut","grams":60,"display":"½ cup grated"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Masala Dosa","description":"Crisp dosa filled with a turmeric potato-onion masala.","cuisine":"indian","meal_types":["breakfast"],"servings":3,"prep":20,"cook":30,"steps":["Make and ferment the dosa batter as for plain dosa (soak 5 hours, grind with salt, rest overnight).","Boil and roughly mash the potatoes.","Heat 1 tbsp oil, splutter mustard seeds, add onion and green chilli, then turmeric, potatoes and a splash of water; cook 3 minutes.","Cook thin dosas on a hot tawa with a little oil, fill with the potato masala and fold."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"urad dal","grams":50,"display":"¼ cup"},{"ingredient":"potato","grams":250,"display":"2 medium"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"sunflower oil","grams":25,"display":"5 tsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"salt","grams":5,"display":"1 tsp"}]},{"title":"Pesarattu (Green Moong Dosa)","description":"Andhra-style dosa made from moong dal — no fermenting needed.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":15,"cook":15,"steps":["Soak moong dal and rice for 4 hours. Grind with ginger, green chilli and salt to a smooth batter.","Spread thin on a hot tawa, sprinkle chopped onion, drizzle oil and cook until crisp."],"lines":[{"ingredient":"moong dal","grams":150,"display":"¾ cup (dry)"},{"ingredient":"rice","grams":30,"display":"2 tbsp"},{"ingredient":"ginger","grams":5,"display":"1 tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Aloo Paratha with Curd","description":"Whole-wheat flatbreads stuffed with spiced potato, served with curd.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":20,"cook":20,"steps":["Knead the atta with a pinch of salt and water into a soft dough; rest 15 minutes.","Boil and mash the potatoes with green chilli, coriander, chilli powder and salt.","Stuff a ball of filling into each dough ball, seal and roll out gently.","Cook on a hot tawa with a little ghee until golden on both sides. Serve with curd."],"lines":[{"ingredient":"whole wheat flour","grams":150,"display":"1¼ cups"},{"ingredient":"potato","grams":200,"display":"2 medium"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"curd","grams":150,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Paneer Paratha","description":"Whole-wheat parathas stuffed with crumbled spiced paneer.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":20,"cook":15,"steps":["Knead the atta with water into a soft dough; rest 15 minutes.","Mix the crumbled paneer with chopped green chilli, coriander and salt.","Stuff, seal and roll the parathas, then cook on a hot tawa with a little ghee until golden."],"lines":[{"ingredient":"whole wheat flour","grams":150,"display":"1¼ cups"},{"ingredient":"paneer","grams":100,"display":"½ cup crumbled"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Gobi Paratha with Curd","description":"Parathas stuffed with grated cauliflower, ginger and green chilli.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":20,"cook":20,"steps":["Knead the atta into a soft dough and rest 15 minutes.","Mix grated cauliflower with salt, leave 5 minutes, squeeze out the water, then add ginger, chilli and coriander.","Stuff, roll and cook the parathas on a hot tawa with a little ghee. Serve with curd."],"lines":[{"ingredient":"whole wheat flour","grams":150,"display":"1¼ cups"},{"ingredient":"cauliflower","grams":150,"display":"1½ cups grated"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"ginger","grams":5,"display":"1 tsp grated"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"curd","grams":150,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Mint Chutney Vegetable Sandwich","description":"Whole-wheat sandwich with fresh mint-coriander chutney, cucumber, tomato and capsicum.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":15,"cook":0,"steps":["Grind mint, coriander, green chilli, lemon and salt with a spoon of water into a thick chutney.","Butter the bread and spread with the chutney.","Layer thinly sliced cucumber, tomato and capsicum, season with pepper, close and cut."],"lines":[{"ingredient":"whole wheat bread","grams":160,"display":"6 slices"},{"ingredient":"butter","grams":10,"display":"2 tsp"},{"ingredient":"cucumber","grams":60,"display":"½"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"capsicum","grams":30,"display":"¼"},{"ingredient":"mint leaves","grams":5,"display":"¼ cup"},{"ingredient":"coriander leaves","grams":10,"display":"½ cup"},{"ingredient":"green chilli","grams":3,"display":"½"},{"ingredient":"lemon","grams":10,"display":"a squeeze"},{"ingredient":"black pepper","grams":1,"display":"a pinch"},{"ingredient":"salt","grams":2,"display":"a pinch"}]},{"title":"Peanut Butter Banana Toast","description":"Whole-wheat toast with peanut butter and sliced banana.","cuisine":"international","meal_types":["breakfast"],"servings":1,"prep":5,"cook":3,"steps":["Toast the bread.","Spread with peanut butter and top with sliced banana."],"lines":[{"ingredient":"whole wheat bread","grams":80,"display":"2 slices"},{"ingredient":"peanut butter","grams":32,"display":"2 tbsp"},{"ingredient":"banana","grams":120,"display":"1"}]},{"title":"Egg Bhurji with Toast","description":"Indian-style scrambled eggs with onion, tomato and green chilli.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":5,"cook":10,"steps":["Heat the oil, cook onion and green chilli 2 minutes, then tomato, turmeric and salt for 2 minutes.","Pour in the beaten eggs and stir gently over low heat until just set.","Scatter coriander and serve with toast."],"lines":[{"ingredient":"eggs","grams":200,"display":"4"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"whole wheat bread","grams":120,"display":"4 slices"}]},{"title":"Masala Omelette","description":"Fluffy three-egg omelette with onion, tomato and chilli.","cuisine":"indian","meal_types":["breakfast"],"servings":1,"prep":5,"cook":5,"steps":["Beat the eggs with salt, pepper and the chopped vegetables and coriander.","Pour into a hot oiled pan, cook until the base sets, then fold or flip and cook 1 more minute."],"lines":[{"ingredient":"eggs","grams":150,"display":"3"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"tomato","grams":40,"display":"½"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"salt","grams":2,"display":"a pinch"},{"ingredient":"black pepper","grams":1,"display":"a pinch"}]},{"title":"Moong Sprouts Salad","description":"Crunchy sprouted moong with vegetables, peanuts and lemon.","cuisine":"indian","meal_types":["breakfast"],"servings":1,"prep":10,"cook":3,"steps":["Steam or blanch the sprouts for 2–3 minutes and cool.","Toss with the chopped vegetables, green chilli, peanuts, salt, lemon juice and coriander."],"lines":[{"ingredient":"moong sprouts","grams":200,"display":"2 cups"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"cucumber","grams":60,"display":"½"},{"ingredient":"peanuts","grams":30,"display":"3 tbsp roasted"},{"ingredient":"lemon","grams":30,"display":"½"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"green chilli","grams":3,"display":"½"},{"ingredient":"salt","grams":2,"display":"a pinch"}]},{"title":"Sabudana Khichdi","description":"Tapioca pearls with peanuts, potato and cumin — a Maharashtrian favourite.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":15,"steps":["Rinse the sabudana, soak overnight in just enough water to cover, and drain.","Coarsely crush the peanuts and mix with the sabudana, salt and sugar.","Heat the ghee, add cumin, green chilli and diced boiled potato; cook 2 minutes.","Add the sabudana mix and cook on low heat 5–6 minutes, stirring, until the pearls turn translucent. Finish with lemon and coriander."],"lines":[{"ingredient":"sabudana","grams":150,"display":"1 cup"},{"ingredient":"peanuts","grams":40,"display":"¼ cup roasted"},{"ingredient":"potato","grams":100,"display":"1"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"ghee","grams":10,"display":"2 tsp"},{"ingredient":"lemon","grams":15,"display":"¼"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"sugar","grams":5,"display":"1 tsp"}]},{"title":"Vegetable Dalia","description":"Savoury broken wheat cooked with vegetables — filling and high in fibre.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":20,"steps":["Dry-roast the dalia for 3 minutes.","Heat the oil in a pressure cooker, add cumin and onion, then the vegetables, turmeric and salt.","Add the dalia and 500 ml water; pressure-cook for 3 whistles. Garnish with coriander."],"lines":[{"ingredient":"broken wheat","grams":100,"display":"½ cup"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"carrot","grams":40,"display":"½"},{"ingredient":"green peas","grams":40,"display":"¼ cup"},{"ingredient":"tomato","grams":50,"display":"1 small"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"}]},{"title":"Sweet Dalia with Milk","description":"Broken wheat porridge cooked in milk with jaggery, almonds and raisins.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":5,"cook":20,"steps":["Roast the dalia for 3 minutes, add 250 ml water and cook until soft (about 10 minutes).","Add the milk and simmer 5 minutes, then stir in the jaggery off the heat.","Top with chopped almonds and raisins."],"lines":[{"ingredient":"broken wheat","grams":80,"display":"⅓ cup"},{"ingredient":"milk","grams":400,"display":"1⅔ cups"},{"ingredient":"jaggery","grams":25,"display":"2 tbsp"},{"ingredient":"almonds","grams":10,"display":"6–8"},{"ingredient":"raisins","grams":15,"display":"1 tbsp"}]},{"title":"Onion Tomato Uttapam","description":"Thick dosa-batter pancakes topped with onion, tomato and capsicum.","cuisine":"indian","meal_types":["breakfast"],"servings":3,"prep":20,"cook":20,"steps":["Make and ferment dosa batter (soak rice and urad dal 5 hours, grind with salt, rest overnight).","Pour a thick circle of batter onto a hot tawa and press the chopped vegetables and coriander on top.","Drizzle oil around, cook until the base is golden, flip and cook 1–2 minutes more."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"urad dal","grams":50,"display":"¼ cup"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"capsicum","grams":40,"display":"⅓"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"sunflower oil","grams":20,"display":"4 tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Tofu Bhurji","description":"A vegan take on egg bhurji with crumbled tofu and vegetables.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":10,"cook":10,"steps":["Heat the oil, cook onion, green chilli and capsicum for 3 minutes, then add tomato, turmeric and salt.","Crumble in the tofu and cook 4–5 minutes, stirring. Finish with coriander."],"lines":[{"ingredient":"tofu","grams":300,"display":"1½ blocks"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"capsicum","grams":40,"display":"⅓"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":2,"display":"a pinch"}]},{"title":"Chickpea Chaat","description":"Tangy boiled chickpeas with onion, tomato, cucumber and lemon.","cuisine":"indian","meal_types":["breakfast","lunch"],"servings":2,"prep":10,"cook":30,"steps":["Soak the chickpeas overnight and pressure-cook with salt until soft (5–6 whistles). Drain and cool.","Toss with the chopped vegetables, green chilli, crushed roasted cumin, lemon juice and coriander."],"lines":[{"ingredient":"chickpeas","grams":140,"display":"¾ cup (dry)"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"cucumber","grams":50,"display":"½"},{"ingredient":"lemon","grams":20,"display":"⅓"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"green chilli","grams":3,"display":"½"},{"ingredient":"cumin seeds","grams":1,"display":"¼ tsp roasted"},{"ingredient":"salt","grams":2,"display":"a pinch"}]},{"title":"Masala Thepla with Curd","description":"Soft Gujarati spiced flatbreads made with atta, besan and curd.","cuisine":"indian","meal_types":["breakfast"],"servings":2,"prep":20,"cook":20,"steps":["Mix the atta, besan, spices, salt, chopped coriander, 1 tsp oil and 60 g of the curd; knead to a soft dough with water.","Roll into thin circles and cook on a hot tawa with a little oil until spotted golden.","Serve with the rest of the curd."],"lines":[{"ingredient":"whole wheat flour","grams":150,"display":"1¼ cups"},{"ingredient":"besan","grams":30,"display":"¼ cup"},{"ingredient":"curd","grams":160,"display":"⅔ cup"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"coriander leaves","grams":10,"display":"¼ cup"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Banana Peanut Butter Smoothie","description":"Milk, banana, oats and peanut butter blended into a filling breakfast drink.","cuisine":"international","meal_types":["breakfast"],"servings":1,"prep":5,"cook":0,"steps":["Blend everything until smooth. Add a few ice cubes if you like it cold."],"lines":[{"ingredient":"milk","grams":300,"display":"1¼ cups"},{"ingredient":"banana","grams":120,"display":"1"},{"ingredient":"rolled oats","grams":30,"display":"⅓ cup"},{"ingredient":"peanut butter","grams":16,"display":"1 tbsp"}]},{"title":"Dal Tadka with Rice","description":"Toor dal finished with a garlic-cumin ghee tadka, served with steamed rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":30,"steps":["Pressure-cook the rinsed dal with turmeric, salt and 400 ml water for 4 whistles; whisk smooth.","Cook the rice in 2 cups water until tender.","Heat the ghee, add cumin and garlic, then onion, tomato and chilli powder; cook 5 minutes and pour into the dal.","Simmer 3 minutes and garnish with coriander. Serve with the rice."],"lines":[{"ingredient":"toor dal","grams":100,"display":"½ cup"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"ghee","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Jain Dal with Jeera Rice","description":"Tomato toor dal without onion or garlic, with cumin rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":30,"steps":["Pressure-cook the dal with turmeric, salt and 400 ml water for 4 whistles; whisk smooth.","Heat half the ghee, add half the cumin, then tomato and chilli powder; cook 3 minutes and add to the dal.","For the rice, fry the rest of the cumin in the rest of the ghee, add rice and 2 cups water and cook until tender."],"lines":[{"ingredient":"toor dal","grams":100,"display":"½ cup"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":4,"display":"1 tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Rajma Chawal","description":"Punjabi kidney-bean curry with steamed rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":45,"steps":["Soak the rajma overnight, then pressure-cook with salt and fresh water for 6–7 whistles until very soft.","Heat the oil, add cumin, then onion; fry golden. Add ginger, garlic, tomato and spices and cook until the oil separates.","Add the rajma with its liquid and simmer 15 minutes, mashing a few beans to thicken. Serve with rice."],"lines":[{"ingredient":"rajma","grams":100,"display":"½ cup (dry)"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":8,"display":"2 tsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Chole with Roti","description":"Spiced chickpea curry with whole-wheat rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":45,"steps":["Soak the chickpeas overnight and pressure-cook with salt for 5–6 whistles.","Fry cumin and onion in the oil until golden; add ginger, garlic, tomato and spices and cook 8 minutes.","Add the chickpeas and some cooking water; simmer 15 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"chickpeas","grams":100,"display":"½ cup (dry)"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":8,"display":"2 tsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Jain Chole with Roti","description":"Chickpea curry with tomato and spices — no onion, garlic or ginger.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":45,"steps":["Soak the chickpeas overnight and pressure-cook with salt for 5–6 whistles.","Heat the oil, add cumin, then pureed tomato and the spices; cook until thick.","Add the chickpeas and some cooking water, simmer 15 minutes and finish with lemon.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"chickpeas","grams":100,"display":"½ cup (dry)"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"tomato","grams":150,"display":"2"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"lemon","grams":15,"display":"¼"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Palak Paneer with Roti","description":"Paneer cubes in a smooth garlicky spinach gravy, with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Blanch the spinach 2 minutes, cool in cold water and blend smooth.","Heat the oil, add cumin, onion, ginger and garlic; cook 3 minutes, then tomato for 3 minutes.","Add the spinach puree and salt, simmer 5 minutes, then add the paneer and heat through.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"spinach","grams":250,"display":"1 bunch"},{"ingredient":"paneer","grams":150,"display":"1 cup cubed"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Jain Palak Paneer with Roti","description":"Spinach and paneer cooked with tomato and cumin — no onion, garlic or ginger.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Blanch the spinach with the green chilli, cool and blend smooth.","Heat the ghee, add cumin and chopped tomato; cook 4 minutes.","Add the spinach and salt, simmer 5 minutes, then add paneer and heat through.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"spinach","grams":250,"display":"1 bunch"},{"ingredient":"paneer","grams":150,"display":"1 cup cubed"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"ghee","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Matar Paneer with Roti","description":"Peas and paneer in an onion-tomato gravy, with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Blend onion, tomato, ginger and garlic into a paste.","Cook the paste in the oil with the spices until thick and the oil separates (8–10 minutes).","Add peas and 200 ml water, simmer 8 minutes, then add paneer and simmer 3 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"green peas","grams":120,"display":"¾ cup"},{"ingredient":"paneer","grams":120,"display":"¾ cup cubed"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Aloo Gobi with Roti","description":"Dry potato and cauliflower sabzi with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Heat the oil, add cumin, onion and ginger; cook 2 minutes.","Add cubed potato, cauliflower florets, spices and salt; cover and cook on low heat 15 minutes, stirring now and then.","Add chopped tomato and cook uncovered 5 minutes more.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"potato","grams":200,"display":"2 medium"},{"ingredient":"cauliflower","grams":250,"display":"½ head"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Bhindi Masala with Roti","description":"Stir-fried okra with onion, tomato and spices, with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Wash and fully dry the okra before slicing (this stops it going slimy).","Fry the okra in the oil on medium-high heat for 8 minutes until lightly browned; push aside.","Add cumin and onion, cook 3 minutes, then tomato, spices and salt; toss everything together for 3 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"okra","grams":250,"display":"2 cups sliced"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Jain Bhindi with Roti","description":"Okra stir-fried with tomato and dry spices — Jain friendly.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Dry the okra well, slice, and fry in the oil for 8 minutes until lightly browned.","Add cumin, chopped tomato, spices and salt; cook 4 minutes, tossing.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"okra","grams":250,"display":"2 cups sliced"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Baingan Bharta with Roti","description":"Smoky roasted brinjal mashed with onion, tomato and garlic.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":30,"steps":["Roast the brinjal directly over a gas flame, turning, until charred and soft (10–12 minutes). Cool, peel and mash.","Fry cumin, garlic, green chilli and onion in the oil until soft, then tomato and chilli powder for 4 minutes.","Add the mashed brinjal and salt and cook 5 minutes. Garnish with coriander.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"brinjal","grams":400,"display":"1 large"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Lauki Chana Dal with Rice","description":"Bottle gourd and chana dal cooked together — light, Jain friendly and vegan.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":30,"steps":["Soak the chana dal 1 hour.","Heat the oil, add cumin and tomato, then the lauki, dal, spices, salt and 400 ml water.","Pressure-cook for 3 whistles. Serve with rice cooked in 2 cups water."],"lines":[{"ingredient":"bottle gourd","grams":250,"display":"2 cups cubed"},{"ingredient":"chana dal","grams":80,"display":"⅓ cup"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Mixed Vegetable Sabzi with Roti","description":"Seasonal vegetables in a light onion-tomato masala, with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Heat the oil, add cumin and onion and cook 3 minutes, then tomato and spices for 3 minutes.","Add the chopped vegetables, salt and a splash of water; cover and cook 12–15 minutes until tender.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"carrot","grams":80,"display":"1"},{"ingredient":"french beans","grams":80,"display":"¾ cup"},{"ingredient":"green peas","grams":80,"display":"½ cup"},{"ingredient":"cauliflower","grams":120,"display":"1 cup"},{"ingredient":"potato","grams":100,"display":"1"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Jain Mixed Vegetable with Roti","description":"Beans, peas, cauliflower, capsicum and cabbage — no onion, garlic or roots.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Heat the oil, add cumin, then tomato and spices; cook 3 minutes.","Add the vegetables and salt, cover and cook 12 minutes until tender.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"french beans","grams":100,"display":"1 cup"},{"ingredient":"green peas","grams":80,"display":"½ cup"},{"ingredient":"cauliflower","grams":150,"display":"1½ cups"},{"ingredient":"capsicum","grams":80,"display":"¾"},{"ingredient":"cabbage","grams":100,"display":"1 cup shredded"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Cabbage Peas Sabzi with Roti","description":"Quick patta gobi matar with a mustard-seed tempering.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":15,"steps":["Heat the oil, splutter the mustard seeds, add green chilli and turmeric.","Add cabbage, peas and salt; cover and cook 10 minutes, stirring once or twice.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"cabbage","grams":300,"display":"3 cups shredded"},{"ingredient":"green peas","grams":100,"display":"⅔ cup"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Kadhi Chawal","description":"Tangy curd and besan kadhi with steamed rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":30,"steps":["Whisk the curd, besan, turmeric, salt and 500 ml water until smooth.","Heat the ghee, splutter mustard and cumin seeds, add green chilli, then pour in the curd mix.","Bring to a boil while stirring, then simmer 20 minutes until thickened. Add chilli powder and serve with rice."],"lines":[{"ingredient":"besan","grams":50,"display":"½ cup"},{"ingredient":"curd","grams":300,"display":"1¼ cups"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"ghee","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Curd Rice","description":"South Indian comfort food: rice mixed with curd and tempered with mustard seeds.","cuisine":"indian","meal_types":["lunch"],"servings":2,"prep":10,"cook":20,"steps":["Cook the rice until very soft and let it cool.","Mash lightly and mix in the curd, salt and grated cucumber.","Temper mustard seeds and green chilli in the oil and pour over. Garnish with coriander."],"lines":[{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"curd","grams":300,"display":"1¼ cups"},{"ingredient":"cucumber","grams":60,"display":"½"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"sunflower oil","grams":8,"display":"2 tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Vegetable Pulao with Raita","description":"Fragrant ghee rice with vegetables and cucumber raita.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Soak the rice 20 minutes.","Heat the ghee, add cumin and sliced onion; cook until light golden, then add the vegetables for 2 minutes.","Add the drained rice, salt and 300 ml water; cover and cook on low heat 15 minutes.","For the raita, mix the curd with grated cucumber and a pinch of salt."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"carrot","grams":50,"display":"½"},{"ingredient":"french beans","grams":50,"display":"½ cup"},{"ingredient":"green peas","grams":60,"display":"⅓ cup"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"curd","grams":150,"display":"⅔ cup"},{"ingredient":"cucumber","grams":60,"display":"½"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Moong Dal with Jeera Rice","description":"Simple yellow moong dal with cumin rice — Jain friendly.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Pressure-cook the moong dal with turmeric, salt, tomato and 400 ml water for 3 whistles.","Temper half the cumin and the green chilli in half the ghee and pour over the dal.","Fry the rest of the cumin in the rest of the ghee, add rice and 2 cups water and cook until tender."],"lines":[{"ingredient":"moong dal","grams":100,"display":"½ cup"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"ghee","grams":12,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":4,"display":"1 tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"salt","grams":4,"display":"¾ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"}]},{"title":"Moong Dal Khichdi","description":"Soft one-pot rice and moong dal with ghee — easy on the stomach.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Rinse the rice and dal together.","Heat the ghee in a pressure cooker, add cumin, then rice, dal, peas, turmeric, salt and 900 ml water.","Pressure-cook for 4 whistles; stir well before serving."],"lines":[{"ingredient":"rice","grams":100,"display":"½ cup"},{"ingredient":"moong dal","grams":80,"display":"⅓ cup"},{"ingredient":"green peas","grams":40,"display":"¼ cup"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Masoor Dal with Rice","description":"Quick-cooking red lentil dal with garlic, served with rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Boil the masoor dal with turmeric, salt and 500 ml water for 15 minutes until soft.","Fry cumin, garlic and onion in the oil, then add tomato and chilli powder; cook 4 minutes and stir into the dal.","Serve with rice cooked in 2 cups water."],"lines":[{"ingredient":"masoor dal","grams":100,"display":"½ cup"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Sambar Rice","description":"Toor dal and vegetable sambar with tamarind, served with rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":35,"steps":["Pressure-cook the dal with turmeric and 350 ml water for 4 whistles; mash.","Soak the tamarind in 150 ml warm water and squeeze out the pulp.","Boil the chopped vegetables in the tamarind water with the spices and salt until tender, then add the dal and simmer 5 minutes.","Temper mustard seeds in the oil, pour over and serve with rice."],"lines":[{"ingredient":"toor dal","grams":80,"display":"⅓ cup"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"brinjal","grams":80,"display":"1 small"},{"ingredient":"okra","grams":60,"display":"6 pods"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tamarind","grams":15,"display":"small lemon-sized ball"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Tomato Rasam with Rice","description":"Thin, peppery tomato-tamarind soup over rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Pressure-cook the dal with 250 ml water; mash and thin with 300 ml water.","Crush the pepper, cumin and garlic coarsely.","Simmer chopped tomato with tamarind pulp, the crushed spices and salt for 8 minutes, add the dal water and bring to a froth — don''t boil hard.","Temper mustard seeds in the oil, pour over, add coriander and serve with rice."],"lines":[{"ingredient":"toor dal","grams":50,"display":"¼ cup"},{"ingredient":"tomato","grams":200,"display":"3"},{"ingredient":"tamarind","grams":10,"display":"small ball"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"black pepper","grams":2,"display":"½ tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"sunflower oil","grams":8,"display":"2 tsp"},{"ingredient":"rice","grams":140,"display":"¾ cup"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Vegetable Biryani","description":"Layered rice and spiced vegetables with mint, curd and ghee.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":20,"cook":35,"steps":["Soak the rice 20 minutes, then boil in salted water until 70% cooked; drain.","Fry the sliced onion in the ghee until brown; remove half for the top.","Add ginger, garlic, the vegetables, curd, spices and salt; cook 8 minutes.","Layer the rice over the vegetables with mint and fried onion, cover tightly and cook on the lowest heat 15 minutes."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"carrot","grams":60,"display":"½"},{"ingredient":"french beans","grams":60,"display":"½ cup"},{"ingredient":"green peas","grams":60,"display":"⅓ cup"},{"ingredient":"cauliflower","grams":80,"display":"¾ cup"},{"ingredient":"onion","grams":100,"display":"1 large"},{"ingredient":"curd","grams":100,"display":"½ cup"},{"ingredient":"ghee","grams":20,"display":"4 tsp"},{"ingredient":"mint leaves","grams":10,"display":"½ cup"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":5,"display":"1 tsp"}]},{"title":"Soya Chunks Curry with Rice","description":"High-protein soya chunks in an onion-tomato curry, with rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Boil the soya chunks 5 minutes, rinse in cold water and squeeze dry.","Cook onion, ginger and garlic in the oil until golden; add tomato and spices and cook 6 minutes.","Add the chunks, salt and 250 ml water; simmer 10 minutes. Serve with rice."],"lines":[{"ingredient":"soya chunks","grams":60,"display":"1 cup"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Tofu Matar with Roti","description":"Tofu and green peas in a spiced tomato gravy — a vegan matar paneer.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Press the tofu dry and cut into cubes.","Fry cumin, onion and ginger in the oil, then tomato and coriander powder until thick.","Add peas, salt and 200 ml water; simmer 6 minutes, add the tofu and simmer 3 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"tofu","grams":200,"display":"1 block"},{"ingredient":"green peas","grams":100,"display":"⅔ cup"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Chana Dal Tadka with Roti","description":"Nutty split chickpea dal with a ghee and garlic tadka.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":35,"steps":["Soak the chana dal 1 hour, then pressure-cook with turmeric, salt and 450 ml water for 5 whistles.","Fry cumin, garlic and onion in the ghee, add tomato and chilli powder, cook 4 minutes and mix into the dal.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"chana dal","grams":100,"display":"½ cup"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"ghee","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Kadai Paneer with Roti","description":"Paneer and capsicum tossed in a spicy onion-tomato masala.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Fry the capsicum and half the onion (in chunks) in the oil for 3 minutes; set aside.","In the same pan cook the rest of the onion, ginger, garlic, tomato and spices until thick.","Add paneer, the capsicum and onion, salt and a splash of water; toss 3 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"paneer","grams":150,"display":"1 cup cubed"},{"ingredient":"capsicum","grams":150,"display":"1 large"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Jain Paneer Capsicum Sabzi with Roti","description":"Paneer and capsicum in a tomato masala — no onion, garlic or ginger.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Heat the oil, add cumin and the capsicum; cook 3 minutes.","Add pureed tomato, spices and salt; cook until thick.","Add the paneer and toss 3 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"paneer","grams":150,"display":"1 cup cubed"},{"ingredient":"capsicum","grams":150,"display":"1 large"},{"ingredient":"tomato","grams":150,"display":"2"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Mushroom Matar with Roti","description":"Mushrooms and peas in a light onion-tomato curry.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Fry cumin, onion and garlic in the oil until soft; add tomato and coriander powder and cook 4 minutes.","Add mushrooms, peas and salt; cook 8–10 minutes until the mushrooms are tender.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"mushroom","grams":200,"display":"2 cups sliced"},{"ingredient":"green peas","grams":100,"display":"⅔ cup"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Dal Palak with Rice","description":"Toor dal cooked with spinach and garlic, served with rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":30,"steps":["Pressure-cook the dal with turmeric, salt and 400 ml water for 4 whistles.","Fry cumin and garlic in the oil, add tomato and chopped spinach and cook 4 minutes.","Stir in the dal and chilli powder and simmer 5 minutes. Serve with rice."],"lines":[{"ingredient":"toor dal","grams":100,"display":"½ cup"},{"ingredient":"spinach","grams":150,"display":"½ bunch"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Jain Moong Dal Palak with Rice","description":"Moong dal with spinach and tomato — no onion or garlic.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Pressure-cook the moong dal with turmeric, salt and 400 ml water for 3 whistles.","Heat the ghee, add cumin, tomato and chopped spinach; cook 4 minutes, then add the dal and simmer 3 minutes.","Serve with rice."],"lines":[{"ingredient":"moong dal","grams":100,"display":"½ cup"},{"ingredient":"spinach","grams":150,"display":"½ bunch"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"ghee","grams":10,"display":"2 tsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Chickpea Salad Bowl","description":"A filling salad of chickpeas, crunchy vegetables and lemon dressing.","cuisine":"indian","meal_types":["lunch"],"servings":1,"prep":15,"cook":30,"steps":["Soak the chickpeas overnight and pressure-cook with salt until tender; drain and cool.","Chop the vegetables and toss with the chickpeas.","Whisk the lemon juice, oil, salt and pepper, pour over and mix in the coriander."],"lines":[{"ingredient":"chickpeas","grams":100,"display":"½ cup (dry)"},{"ingredient":"cucumber","grams":100,"display":"1 small"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"onion","grams":40,"display":"½"},{"ingredient":"capsicum","grams":50,"display":"½"},{"ingredient":"lemon","grams":30,"display":"½"},{"ingredient":"sunflower oil","grams":8,"display":"2 tsp"},{"ingredient":"coriander leaves","grams":10,"display":"¼ cup"},{"ingredient":"salt","grams":2,"display":"a pinch"},{"ingredient":"black pepper","grams":1,"display":"a pinch"}]},{"title":"Lemon Rice with Peanuts","description":"Tangy turmeric rice with crunchy peanuts — no onion or garlic.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":20,"steps":["Cook the rice so the grains stay separate, and spread it out to cool.","Heat the oil, splutter the mustard seeds, fry the peanuts golden, then add green chilli and turmeric.","Add the rice and salt, toss well, then squeeze over the lemon and add coriander."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"peanuts","grams":40,"display":"¼ cup"},{"ingredient":"lemon","grams":60,"display":"1"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Coconut Rice","description":"South Indian rice tossed with fresh coconut and cashews.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":20,"steps":["Cook the rice so the grains stay separate and let it cool.","Heat the oil, splutter the mustard seeds, fry the cashews and green chilli, then add the coconut for 2 minutes.","Add the rice and salt and toss gently."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"fresh coconut","grams":80,"display":"⅔ cup grated"},{"ingredient":"cashews","grams":15,"display":"10"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"mustard seeds","grams":2,"display":"½ tsp"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Tomato Rice","description":"One-pot rice cooked with tomatoes, onion and peas.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Heat the oil, add cumin and onion and cook 3 minutes.","Add chopped tomato, spices and salt and cook until soft; add peas.","Add the rinsed rice and 300 ml water, cover and cook on low heat 15 minutes."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"tomato","grams":200,"display":"3"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"green peas","grams":60,"display":"⅓ cup"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Egg Curry with Rice","description":"Boiled eggs in a spiced onion-tomato gravy, with rice.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Hard-boil the eggs (10 minutes), peel and make a few shallow slits in each.","Fry onion, ginger and garlic in the oil until golden; add tomato and spices and cook until thick.","Add 250 ml water and salt, simmer 5 minutes, add the eggs and simmer 5 minutes more. Serve with rice."],"lines":[{"ingredient":"eggs","grams":200,"display":"4"},{"ingredient":"onion","grams":100,"display":"1 large"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Egg Fried Rice","description":"Indo-Chinese fried rice with scrambled egg and crunchy vegetables.","cuisine":"indo-chinese","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":15,"steps":["Cook the rice so the grains stay separate, and cool completely (day-old rice works best).","Scramble the eggs in half the oil and set aside.","Stir-fry the finely chopped vegetables in the rest of the oil on high heat for 3 minutes.","Add the rice, soy sauce, pepper, salt and the egg; toss on high heat for 2 minutes."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"eggs","grams":150,"display":"3"},{"ingredient":"carrot","grams":50,"display":"½"},{"ingredient":"french beans","grams":50,"display":"½ cup"},{"ingredient":"capsicum","grams":50,"display":"½"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"soy sauce","grams":15,"display":"1 tbsp"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"black pepper","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":2,"display":"a pinch"}]},{"title":"Egg Bhurji with Roti","description":"Spiced scrambled eggs with onion and tomato, with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":10,"steps":["Cook onion and green chilli in the oil 2 minutes, then tomato, spices and salt for 3 minutes.","Add the beaten eggs and stir over low heat until just set. Add coriander.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"eggs","grams":200,"display":"4"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":80,"display":"1"},{"ingredient":"green chilli","grams":5,"display":"1"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":1,"display":"¼ tsp"},{"ingredient":"coriander leaves","grams":5,"display":"2 tbsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Chicken Curry with Rice","description":"Home-style chicken curry with onion, tomato and curd.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":35,"steps":["Cut the chicken into pieces and mix with curd, turmeric and salt; rest 20 minutes.","Fry onion, ginger and garlic in the oil until golden brown, then tomato and spices until the oil separates.","Add the chicken and 200 ml water; cover and simmer 20 minutes until cooked through. Serve with rice."],"lines":[{"ingredient":"chicken breast","grams":300,"display":"300 g"},{"ingredient":"onion","grams":100,"display":"1 large"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"curd","grams":60,"display":"¼ cup"},{"ingredient":"ginger","grams":8,"display":"2 tsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Chicken Biryani","description":"Layered basmati rice and marinated chicken with mint and fried onion.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":30,"cook":40,"steps":["Marinate the chicken with curd, ginger, garlic, spices, half the mint and salt for at least 30 minutes.","Soak the rice 20 minutes and boil in salted water until 70% cooked; drain.","Fry the sliced onion in the ghee until brown, add the chicken and cook 10 minutes.","Layer the rice on top with the rest of the mint, cover tightly and cook on the lowest heat for 20 minutes."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"chicken breast","grams":250,"display":"250 g"},{"ingredient":"onion","grams":120,"display":"1 large"},{"ingredient":"curd","grams":100,"display":"½ cup"},{"ingredient":"ghee","grams":20,"display":"4 tsp"},{"ingredient":"mint leaves","grams":10,"display":"½ cup"},{"ingredient":"ginger","grams":8,"display":"2 tsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":5,"display":"1 tsp"}]},{"title":"Tandoori Chicken with Salad","description":"Oven- or pan-grilled spiced chicken with a fresh kachumber salad — low in carbs.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":20,"cook":25,"steps":["Marinate the chicken in curd, lemon, ginger, garlic, spices, oil and salt for at least 1 hour.","Grill in a hot oven (220 °C) or a heavy pan for 20–25 minutes, turning once, until cooked through.","Chop cucumber, onion and tomato for the salad and season with salt and lemon."],"lines":[{"ingredient":"chicken breast","grams":300,"display":"300 g"},{"ingredient":"curd","grams":80,"display":"⅓ cup"},{"ingredient":"lemon","grams":30,"display":"½"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"red chilli powder","grams":3,"display":"1 tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"sunflower oil","grams":10,"display":"2 tsp"},{"ingredient":"cucumber","grams":150,"display":"1"},{"ingredient":"onion","grams":60,"display":"1 small"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Chicken Keema Matar with Roti","description":"Minced chicken and peas cooked with spices, with rotis.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Fry onion, ginger and garlic in the oil until golden.","Add the minced chicken and cook on high heat until it changes colour, breaking up lumps.","Add tomato, spices, peas and salt; cover and cook 12 minutes.","For the rotis: knead the atta with a pinch of salt and enough water into a soft dough, rest 15 minutes, roll thin and cook on a hot tawa until puffed."],"lines":[{"ingredient":"chicken breast","grams":250,"display":"250 g minced"},{"ingredient":"green peas","grams":100,"display":"⅔ cup"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"whole wheat flour","grams":120,"display":"1 cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Fish Curry with Rice","description":"Coastal-style fish curry with coconut and tamarind.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Rub the fish with turmeric and salt.","Grind the coconut with the spices and a little water to a paste; soak the tamarind and squeeze out the pulp.","Fry onion in the oil, add tomato and the coconut paste and cook 5 minutes; add tamarind water and 150 ml water and bring to a simmer.","Slide in the fish and simmer gently 8–10 minutes without stirring. Serve with rice."],"lines":[{"ingredient":"fish fillet","grams":300,"display":"300 g"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"tamarind","grams":10,"display":"small ball"},{"ingredient":"fresh coconut","grams":40,"display":"⅓ cup grated"},{"ingredient":"sunflower oil","grams":12,"display":"1 tbsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Masala Fish Fry with Salad","description":"Pan-fried spiced fish fillets with a fresh salad.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":20,"cook":15,"steps":["Coat the fish with crushed garlic, lemon juice, turmeric, chilli powder, salt and the besan; rest 15 minutes.","Shallow-fry in the oil 3–4 minutes per side until cooked through.","Serve with sliced cucumber, tomato and onion."],"lines":[{"ingredient":"fish fillet","grams":300,"display":"300 g"},{"ingredient":"besan","grams":20,"display":"2 tbsp"},{"ingredient":"lemon","grams":30,"display":"½"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"red chilli powder","grams":3,"display":"1 tsp"},{"ingredient":"garlic","grams":6,"display":"2 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"cucumber","grams":150,"display":"1"},{"ingredient":"tomato","grams":100,"display":"1 large"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Prawn Masala with Rice","description":"Prawns in a thick spiced onion-tomato masala.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Toss the prawns with turmeric and salt.","Fry onion, ginger and garlic in the oil until golden; add tomato and spices and cook until thick.","Add the prawns and cook 4–5 minutes until pink and curled — don''t overcook. Serve with rice."],"lines":[{"ingredient":"prawns","grams":250,"display":"250 g cleaned"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"ginger","grams":6,"display":"1 tsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":3,"display":"1 tsp"},{"ingredient":"red chilli powder","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":3,"display":"½ tsp"}]},{"title":"Mutton Curry with Rice","description":"Slow-cooked goat curry with onion, tomato and curd.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":20,"cook":60,"steps":["Marinate the mutton in curd, turmeric and salt for 1 hour.","Brown the onion in the oil, add ginger, garlic, tomato and spices and cook until the oil separates.","Add the mutton, sear 5 minutes, then add 400 ml water and pressure-cook 6–7 whistles until tender. Serve with rice."],"lines":[{"ingredient":"mutton","grams":300,"display":"300 g"},{"ingredient":"onion","grams":120,"display":"1 large"},{"ingredient":"tomato","grams":120,"display":"2 small"},{"ingredient":"curd","grams":60,"display":"¼ cup"},{"ingredient":"ginger","grams":8,"display":"2 tsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"coriander powder","grams":4,"display":"1½ tsp"},{"ingredient":"red chilli powder","grams":3,"display":"1 tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Chilli Chicken with Rice","description":"Indo-Chinese stir-fried chicken with capsicum, onion and soy sauce.","cuisine":"indo-chinese","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":20,"steps":["Cut the chicken into bite-size pieces and sear in half the oil until browned; set aside.","Stir-fry garlic, green chilli, onion and capsicum in the rest of the oil on high heat for 3 minutes.","Add the chicken, soy sauce, salt and a splash of water; toss until glossy. Serve with rice."],"lines":[{"ingredient":"chicken breast","grams":250,"display":"250 g"},{"ingredient":"capsicum","grams":100,"display":"1"},{"ingredient":"onion","grams":80,"display":"1"},{"ingredient":"soy sauce","grams":20,"display":"1½ tbsp"},{"ingredient":"garlic","grams":8,"display":"3 cloves"},{"ingredient":"green chilli","grams":6,"display":"2"},{"ingredient":"sunflower oil","grams":15,"display":"1 tbsp"},{"ingredient":"rice","grams":120,"display":"⅔ cup"},{"ingredient":"salt","grams":2,"display":"a pinch"}]},{"title":"Matar Pulao with Raita","description":"Green pea pulao with cumin and ghee, served with cucumber raita.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":10,"cook":25,"steps":["Soak the rice 20 minutes.","Fry cumin and sliced onion in the ghee, add the peas, drained rice, salt and 300 ml water.","Cover and cook on low heat 15 minutes. Mix curd with grated cucumber and salt for the raita."],"lines":[{"ingredient":"rice","grams":150,"display":"¾ cup"},{"ingredient":"green peas","grams":100,"display":"⅔ cup"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":3,"display":"¾ tsp"},{"ingredient":"curd","grams":150,"display":"⅔ cup"},{"ingredient":"cucumber","grams":50,"display":"½"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]},{"title":"Vegetable Khichdi","description":"Rice, moong dal and vegetables cooked soft with ghee — a comforting dinner.","cuisine":"indian","meal_types":["lunch","dinner"],"servings":2,"prep":15,"cook":25,"steps":["Rinse the rice and dal together.","Heat the ghee in a pressure cooker, add cumin and onion, then tomato and the vegetables.","Add rice, dal, turmeric, salt and 900 ml water; pressure-cook 4 whistles."],"lines":[{"ingredient":"rice","grams":100,"display":"½ cup"},{"ingredient":"moong dal","grams":60,"display":"¼ cup"},{"ingredient":"carrot","grams":50,"display":"½"},{"ingredient":"green peas","grams":50,"display":"⅓ cup"},{"ingredient":"potato","grams":80,"display":"1 small"},{"ingredient":"onion","grams":50,"display":"1 small"},{"ingredient":"tomato","grams":60,"display":"1 small"},{"ingredient":"ghee","grams":15,"display":"1 tbsp"},{"ingredient":"cumin seeds","grams":2,"display":"½ tsp"},{"ingredient":"turmeric","grams":1,"display":"¼ tsp"},{"ingredient":"salt","grams":4,"display":"¾ tsp"}]}]'::jsonb;
  v_recipe jsonb;
  v_id bigint;
  v_missing text;
  v_added int := 0;
begin
  insert into public.ingredients (
    name, aliases, fdc_id, kcal_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fiber_per_100g,
    allergen_tags, contains_meat, contains_fish, contains_egg, contains_dairy, contains_honey, jain_avoid,
    aisle, purchase_unit, pack_size, grams_per_piece, grams_per_ml, search_term
  )
  select
    x->>'name',
    array(select jsonb_array_elements_text(x->'aliases')),
    -- If this USDA food is already linked to another ingredient, keep the numbers but not the link.
    case when exists (select 1 from public.ingredients i where i.fdc_id = (x->>'fdc_id')::integer)
      then null else (x->>'fdc_id')::integer end,
    (x->>'kcal')::numeric, (x->>'protein')::numeric, (x->>'carbs')::numeric, (x->>'fat')::numeric, (x->>'fiber')::numeric,
    array(select jsonb_array_elements_text(x->'allergen_tags')),
    (x->>'meat')::boolean, (x->>'fish')::boolean, (x->>'egg')::boolean, (x->>'dairy')::boolean,
    (x->>'honey')::boolean, (x->>'jain')::boolean,
    x->>'aisle', x->>'unit', (x->>'pack')::numeric, (x->>'per_piece')::numeric, (x->>'per_ml')::numeric, x->>'search'
  from jsonb_array_elements(v_ingredients) as x
  where not exists (select 1 from public.ingredients i where i.name = x->>'name');

  -- Every ingredient a recipe needs must exist now, or nothing is saved.
  select string_agg(distinct l->>'ingredient', ', ') into v_missing
  from jsonb_array_elements(v_recipes) as r, jsonb_array_elements(r->'lines') as l
  where not exists (select 1 from public.ingredients i where i.name = l->>'ingredient');
  if v_missing is not null then
    raise exception 'Missing ingredients: %', v_missing;
  end if;

  for v_recipe in select * from jsonb_array_elements(v_recipes) loop
    continue when exists (select 1 from public.recipes where lower(title) = lower(v_recipe->>'title'));

    insert into public.recipes (title, description, cuisine, meal_types, servings, prep_minutes, cook_minutes, steps, status, source)
    values (
      v_recipe->>'title', v_recipe->>'description', v_recipe->>'cuisine',
      array(select jsonb_array_elements_text(v_recipe->'meal_types')),
      (v_recipe->>'servings')::integer, (v_recipe->>'prep')::integer, (v_recipe->>'cook')::integer,
      array(select jsonb_array_elements_text(v_recipe->'steps')),
      'draft', 'ai'
    )
    returning id into v_id;

    insert into public.recipe_ingredients (recipe_id, ingredient_id, position, grams, display_amount)
    select v_id, i.id, (t.ord - 1)::integer, (t.line->>'grams')::numeric, t.line->>'display'
    from jsonb_array_elements(v_recipe->'lines') with ordinality as t(line, ord)
    join public.ingredients i on i.name = t.line->>'ingredient';

    v_added := v_added + 1;
  end loop;

  raise notice 'Starter library: % new draft recipes added.', v_added;
end
$seed$;
